  1→/* ── SUPER DUPER Design System ──────────────────────────────────────
  2→ *  Brand: #00BB81 (Jade Green)
  3→ *  Surfaces: layered depth, no borders/shadows
  4→ *  Typography: Inter (sans) + JetBrains Mono (mono)
  5→ *  Slot colors: official ComfyUI dark theme
  6→ * ──────────────────────────────────────────────────────────────────── */
  7→
  8→@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap");
  9→
 10→/* ── Design Tokens ──────────────────────────────────────────────── */
 11→
 12→:root {
 13→  /* Brand */
 14→  --sd-brand: #00BB81;
 15→  --sd-brand-dim: #00BB8133;
 16→  --sd-brand-subtle: #00BB8118;
 17→  --sd-dark: #020410;
 18→
 19→  /* Surfaces */
 20→  --sd-canvas: #0d0f14;
 21→  --sd-panel: #141620;
 22→  --sd-card: #1a1d2a;
 23→  --sd-card-hover: #1e2133;
 24→  --sd-elevated: #222538;
 25→  --sd-input: #12141e;
 26→
 27→  /* Text */
 28→  --sd-text-primary: #e8e9ed;
 29→  --sd-text-secondary: #9a9caa;
 30→  --sd-text-muted: #5c5e6e;
 31→  --sd-text-accent: #c0c2ce;
 32→  --sd-text-brand: #00BB81;
 33→
 34→  /* Borders */
 35→  --sd-border: #2a2d3a;
 36→  --sd-border-subtle: #1f2230;
 37→
 38→  /* Slot Colors (ComfyUI dark theme) */
 39→  --sd-slot-clip: #FFD500;
 40→  --sd-slot-clip-vision: #A8DADC;
 41→  --sd-slot-conditioning: #FFA931;
 42→  --sd-slot-controlnet: #6EE7B7;
 43→  --sd-slot-image: #64B5F6;
 44→  --sd-slot-latent: #FF9CF9;
 45→  --sd-slot-mask: #81C784;
 46→  --sd-slot-model: #B39DDB;
 47→  --sd-slot-style-model: #C2FFAE;
 48→  --sd-slot-vae: #FF6E6E;
 49→  --sd-slot-noise: #B0B0B0;
 50→  --sd-slot-guider: #66FFFF;
 51→  --sd-slot-sampler: #ECB4B4;
 52→  --sd-slot-sigmas: #CDFFCD;
 53→
 54→  /* Typography */
 55→  --sd-font-sans: "Inter", "SF Pro Display", system-ui, -apple-system, sans-serif;
 56→  --sd-font-mono: "JetBrains Mono", "Fira Code", "SF Mono", "Cascadia Code", monospace;
 57→
 58→  /* Spacing */
 59→  --sd-space-xs: 4px;
 60→  --sd-space-sm: 6px;
 61→  --sd-space-md: 8px;
 62→  --sd-space-lg: 12px;
 63→  --sd-space-xl: 16px;
 64→
 65→  /* Transitions */
 66→  --sd-transition: 150ms ease;
 67→}
 68→
 69→/* ── Layout Shell ───────────────────────────────────────────────── */
 70→
 71→.sd-header {
 72→  display: flex;
 73→  align-items: center;
 74→  justify-content: space-between;
 75→  padding: var(--sd-space-lg) var(--sd-space-xl);
 76→  font-family: var(--sd-font-sans);
 77→  font-size: 14px;
 78→  font-weight: 700;
 79→  letter-spacing: 0.5px;
 80→  color: var(--sd-text-brand);
 81→  border-bottom: 1px solid var(--sd-border);
 82→  background: var(--sd-panel);
 83→  flex-shrink: 0;
 84→}
 85→
 86→.sd-header__title {
 87→  flex: 1;
 88→}
 89→
 90→.sd-header__status {
 91→  font-family: var(--sd-font-mono);
 92→  font-size: 10px;
 93→  font-weight: 400;
 94→  color: var(--sd-text-muted);
 95→  text-transform: uppercase;
 96→  letter-spacing: 0.06em;
 97→}
 98→
 99→.sd-header__status--connecting {
100→  color: var(--sd-slot-conditioning);
101→}
102→
103→.sd-header__status--disconnected {
104→  color: var(--sd-slot-vae);
105→}
106→
107→/* ── Stage Indicator ────────────────────────────────────────────── */
108→
109→.sd-stage-bar {
110→  display: flex;
111→  align-items: center;
112→  gap: var(--sd-space-md);
113→  padding: var(--sd-space-sm) var(--sd-space-xl);
114→  background: var(--sd-brand-subtle);
115→  border-bottom: 1px solid var(--sd-border);
116→  flex-shrink: 0;
117→  font-size: 12px;
118→  animation: sd-pulse 1.5s ease-in-out infinite;
119→}
120→
121→.sd-stage__label {
122→  font-family: var(--sd-font-mono);
123→  color: var(--sd-text-brand);
124→  font-weight: 600;
125→  font-size: 10px;
126→  letter-spacing: 0.06em;
127→  text-transform: uppercase;
128→}
129→
130→.sd-stage__detail {
131→  font-family: var(--sd-font-sans);
132→  color: var(--sd-text-muted);
133→  font-size: 11px;
134→}
135→
136→@keyframes sd-pulse {
137→  0%, 100% { opacity: 1; }
138→  50% { opacity: 0.6; }
139→}
140→
141→/* ── Messages Area ──────────────────────────────────────────────── */
142→
143→.sd-messages {
144→  flex: 1;
145→  overflow-y: auto;
146→  padding: var(--sd-space-lg);
147→  display: flex;
148→  flex-direction: column;
149→  gap: var(--sd-space-md);
150→  background: var(--sd-canvas);
151→}
152→
153→/* ── Message Bubbles ────────────────────────────────────────────── */
154→
155→.sd-message {
156→  display: flex;
157→  flex-direction: column;
158→  gap: 2px;
159→  padding: var(--sd-space-md) 10px;
160→  border-radius: 6px;
161→  font-family: var(--sd-font-sans);
162→  font-size: 12px;
163→  line-height: 1.5;
164→  word-wrap: break-word;
165→}
166→
167→.sd-message--user {
168→  background: var(--sd-card);
169→  align-self: flex-end;
170→  max-width: 90%;
171→}
172→
173→.sd-message--agent {
174→  background: var(--sd-panel);
175→  align-self: flex-start;
176→  max-width: 95%;
177→}
178→
179→.sd-message--system {
180→  background: transparent;
181→  color: var(--sd-text-muted);
182→  font-style: italic;
183→  font-size: 11px;
184→  align-self: center;
185→}
186→
187→.sd-message__label {
188→  font-family: var(--sd-font-mono);
189→  font-size: 10px;
190→  font-weight: 400;
191→  color: var(--sd-text-muted);
192→  text-transform: uppercase;
193→  letter-spacing: 0.06em;
194→}
195→
196→.sd-message--user .sd-message__label {
197→  color: var(--sd-text-accent);
198→}
199→
200→.sd-message--agent .sd-message__label {
201→  color: var(--sd-text-brand);
202→}
203→
204→.sd-message__body {
205→  color: var(--sd-text-secondary);
206→}
207→
208→.sd-message--user .sd-message__body {
209→  color: var(--sd-text-primary);
