456→/**
457→ * Build the body content for a section based on its type.
458→ */
459→function _buildSectionBody(sec) {
460→  const container = document.createDocumentFragment();
461→
462→  switch (sec.type) {
463→    case "flow_chain": {
464→      const chains = sec.data.chains || [sec.data];
465→      for (const chainData of chains) {
466→        const nodes = (chainData.nodes || []).map(n =>
467→          typeof n === "string" ? { label: n, slotType: "model" } : n
468→        );
469→        container.appendChild(createFlowChain(nodes, chainData.label));
470→      }
471→      break;
472→    }
473→
474→    case "slot_tags": {
475→      const wrap = document.createElement("div");
476→      wrap.className = "sd-slot-tags";
477→      for (const tag of (sec.data.tags || [])) {
478→        wrap.appendChild(createSlotTag(tag.label, tag.slotType));
479→      }
480→      container.appendChild(wrap);
481→      break;
482→    }
483→
484→    case "detail_rows": {
485→      for (const row of (sec.data.rows || [])) {
486→        container.appendChild(createDetailRow(row.label, row.value));
487→      }
488→      break;
489→    }
490→
491→    case "capability_rows": {
492→      for (const row of (sec.data.rows || [])) {
493→        container.appendChild(createCapabilityRow(row.label, row.desc, row.color));
494→      }
495→      break;
496→    }
497→
498→    default: {
499→      // Fallback: render as text
500→      if (sec.data && sec.data.text) {
501→        const p = document.createElement("p");
502→        p.className = "sd-text-body";
503→        p.textContent = sec.data.text;
504→        container.appendChild(p);
505→      }
506→    }
507→  }
508→
509→  return container;
510→}
